\n    44\t                break\n    45\t        i += 1\n    46\t\n    47\t    return string[idx : right_brace_idx + 1] if right_brace_idx is not None else None\n    48\t\n    49\t\n    50\tdef remove_boxed(s: str) -> str:\n    51\t    \"\"\"Remove the LaTeX boxed command from a string.\n    52\t\n    53\t    Args:\n    54\t        s: String with format \"\\\\boxed{content}\"\n    55\t\n    56\t    Returns:\n    57\t        The content inside the boxed command\n    58\t    \"\"\"\n    59\t    left = \"\\\\boxed{\"\n    60\t    assert s[: len(left)] == left, f\"box error: {s}\"\n    61\t    assert s[-1] == \"}\", f\"box error: {s}\"\n    62\t    return s[len(left) : -1]\n    63\t\n    64\t\n    65\tclass timeout:\n    66\t\n    67\t    def __init__(self, seconds=1, error_message=\"Timeout\"):\n    68\t        self.seconds = seconds\n    69\t        self.error_message = error_message\n    70\t\n    71\t    def handle_timeout(self, signum, frame):\n    72\t        raise TimeoutError(self.error_message)\n    73\t\n    74\t    def __enter__(self):\n    75\t        signal.signal(signal.SIGALRM, self.handle_timeout)\n    76\t        signal.alarm(self.seconds)\n    77\t\n    78\t    def __exit__(self, type, value, traceback):\n    79\t        signal.alarm(0)\n    80\t\n    81\t\n    82\t# Constants for normalization\n    83\tSUBSTITUTIONS = [\n    84\t    (\"an \", \"\"),\n    85\t    (\"a \", \"\"),\n    86\t    (\".$\", \"$\"),\n    87\t    (\"\\\\$\", \"\"),\n    88\t    (r\"\\ \", \"\"),\n    89\t    (\" \", \"\"),\n    90\t    (\"mbox\", \"text\"),\n    91\t    (\",\\\\text{and}\", \",\"),\n    92\t    (\"\\\\text{and}\", \",\"),\n    93\t    (\"\\\\text{m}\", \"\\\\text{}\"),\n    94\t]\n    95\t\n    96\tREMOVED_EXPRESSIONS = [\n    97\t    \"square\",\n    98\t    \"ways\",\n    99\t    \"integers\",\n   100\t    \"dollars\",\n   101\t    \"mph\",\n   102\t    \"inches\",\n   103\t    \"hours\",\n   104\t    \"km\",\n   105\t    \"units\",\n   106\t    \"\\\\ldots\",\n   107\t    \"sue\",\n   108\t    \"points\",\n   109\t    \"feet\",\n   110\t    \"minutes\",\n   111\t    \"digits\",\n   112\t    \"cents\",\n   113\t    \"degrees\",\n   114\t    \"cm\",\n   115\t    \"gm\",\n   116\t    \"pounds\",\n   117\t    \"meters\",\n   118\t    \"meals\",\n   119\t    \"edges\",\n   120\t    \"students\",\n   121\t    \"childrentickets\",\n   122\t    \"multiples\",\n   123\t    \"\\\\text{s}\",\n   124\t    \"\\\\text{.}\",\n   125\t    \"\\\\text{\\ns}\",\n   126\t    \"\\\\text{}^2\",\n   127\t    \"\\\\text{}^3\",\n   128\t    \"\\\\text{\\n}\",\n   129\t    \"\\\\text{}\",\n   130\t    r\"\\mathrm{th}\",\n   131\t    r\"^\\circ\",\n   132\t    r\"^{\\circ}\",\n   133\t    r\"\\;\",\n   134\t    r\",\\!\",\n   135\t    \"{,}\",\n   136\t    '\"',\n   137\t    \"\\\\dots\",\n   138\t    \"<|im_end|>\",\n   139\t    \"<|endoftext|>\",\n   140\t]\n   141\t\n   142\t\n   143\tdef normalize_final_answer(final_answer: str) -> str:\n   144\t    \"\"\"Normalize a final answer to a quantitative reasoning question.\n   145\t\n   146\t    Args:\n   147\t        final_answer: The answer string to normalize\n   148\t\n   149\t    Returns:\n   150\t        Normalized answer string\n   151\t    \"\"\"\n   152\t    final_answer = str(final_answer)\n   153\t    final_answer = final_answer.split(\"=\")[-1]\n   154\t\n   155\t    # Apply substitutions and removals\n   156\t    for before, after in SUBSTITUTIONS:\n   157\t        final_answer = final_answer.replace(before, after)\n   158\t    for expr in REMOVED_EXPRESSIONS:\n   159\t        final_answer = final_answer.replace(expr, \"\")\n   160\t\n   161\t    # Extract and normalize LaTeX math\n   162\t    final_answer = re.sub(r\"(.*?)(\\$)(.*?)(\\$)(.*)\", \"$\\\\3$\", final_answer)\n   163\t    final_answer = re.sub(r\"(\\\\text\\{)(.*?)(\\})\", \"\\\\2\", final_answer)\n   164\t    final_answer = re.sub(r\"(\\\\textbf\\{)(.*?)(\\})\", \"\\\\2\", final_answer)\n   165\t    final_answer = re.sub(r\"(\\\\overline\\{)(.*?)(\\})\", \"\\\\2\", final_answer)\n   166\t    final_answer = re.sub(r\"(\\\\boxed\\{)(.*)(\\})\", \"\\\\2\", final_answer)\n   167\t\n   168\t    # Normalize shorthand TeX:\n   169\t    #  \\fracab -> \\frac{a}{b}\n   170\t    #  \\frac{abc}{bef} -> \\frac{abc}{bef}\n   171\t    #  \\fracabc -> \\frac{a}{b}c\n   172\t    #  \\sqrta -> \\sqrt{a}\n   173\t    #  \\sqrtab -> sqrt{a}b\n   174\t    final_answer = re.sub(r\"(frac)([^{])(.)\", \"frac{\\\\2}{\\\\3}\", final_answer)\n   175\t    final_answer = re.sub(r\"(sqrt)([^{])\", \"sqrt{\\\\2}\", final_answer)\n   176\t    final_answer = final_answer.replace(\"$\", \"\")\n   177\t\n   178\t    # Normalize numbers\n   179\t    if final_answer.replace(\",\", \"\").isdigit():\n   180\t        final_answer = final_answer.replace(\",\", \"\")\n   181\t\n   182\t    return final_answer.strip()\n   183\t\n   184\t\n   185\tdef is_correct_minerva(\n   186\t    solution_str: str, gt: str, gt_need_extract: bool = False, answer_pattern: str = r\"(?i)Answer\\s*:\\s*([^\\n]+)\"\n   187\t) -> tuple[bool, str]:\n   188\t    \"\"\"Check if the solution is correct according to Minerva criteria.\n   189\t\n   190\t    Args:\n   191\t        solution_str: The solution string to check\n   192\t        gt: The ground truth answer\n   193\t        gt_need_extract: Whether the ground truth needs extraction\n   194\t        answer_pattern: Regex pattern to extract the answer\n   195\t\n   196\t    Returns:\n   197\t        Tuple of (is_correct, normalized_prediction)\n   198\t    \"\"\"\n   199\t    # Extract answer from solution\n   200\t    match = re.findall(answer_pattern, solution_str)\n   201\t    extracted_answer = match[-1] if match else \"[INVALID]\"\n   202\t    pred = normalize_final_answer(extracted_answer)\n   203\t\n   204\t    # Process ground truth\n   205\t    if gt_need_extract:\n   206\t        gt = normalize_final_answer(remove_boxed(last_boxed_only_string(gt)))\n   207\t    else:\n   208\t        gt = normalize_final_answer(gt)\n   209\t\n   210\t    gt = str(int(float(gt)))  # in dapo, all answers are integers\n   211\t\n   212\t    return (pred == gt), pred\n   213\t\n   214\t\n   215\tdef is_correct_strict_box(pred: str, gt: str, pause_tokens_index: list[int] | None = None) -> tuple[int, str | None]:\n   216\t    \"\"\"Check if the prediction is correct using strict boxed answer criteria.\n   217\t\n   218\t    Args:\n   219\t        pred: The prediction string\n   220\t        gt: The ground truth answer\n   221\t        pause_tokens_index: Indices of pause tokens\n   222\t\n   223\t    Returns:\n   224\t        Tuple of (score, extracted_prediction)\n   225\t    \"\"\"\n   226\t    # Extract the relevant part of the prediction\n   227\t    if pause_tokens_index is not None:\n   228\t        assert len(pause_tokens_index) == 4\n   229\t        pred = pred[pause_tokens_index[-1] - 100 :]\n   230\t    else:\n   231\t        pred = pred[-100:]\n   232\t\n   233\t    # Extract and check the boxed answer\n   234\t    boxed_pred = last_boxed_only_string(pred)\n   235\t    extracted_pred = remove_boxed(boxed_pred) if boxed_pred is not None else None\n   236\t\n   237\t    return 1 if (extracted_pred == gt) else -1, extracted_pred\n   238\t\n   239\t\n   240\tdef verify(\n   241\t    solution_str: str, answer: str, strict_box_verify: bool = False, pause_tokens_index: list[int] | None = None\n   242\t) -> bool:\n   243\t    \"\"\"Verify if the solution is correct.\n   244\t\n   245\t    Args:\n   246\t        solution_str: The solution string to verify\n   247\t        answer: The ground truth answer\n   248\t        strict_box_verify: Whether to use strict box verification\n   249\t        pause_tokens_index: Indices of pause tokens\n   250\t\n   251\t    Returns:\n   252\t        True if the solution is correct, False otherwise\n   253\t    \"\"\"\n   254\t    if strict_box_verify:\n   255\t        correct, pred = is_correct_strict_box(solution_str, answer, pause_tokens_index)\n   256\t        return correct == 1, pred\n   257\t\n   258\t    correct, pred = is_correct_minerva(solution_str, answer)\n   259\t    return correct, pred\n   260\t\n   261\t\n   262\tdef compute_score(\n   263\t    solution_str: str,\n   264\t    ground_truth: str,\n   265\t    strict_box_verify: bool = False,\n   266\t    pause_tokens_index: list[int] | None = None,\n   267\t) -> float:\n   268\t    \"\"\"Compute the reward score for a solution.\n   269\t\n   270\t    Args:\n   271\t        solution_str: The solution string\n   272\t        ground_truth: The ground truth answer\n   273\t        config: Configuration object containing reward model settings\n   274\t        pause_tokens_index: Indices of pause tokens\n   275\t\n   276\t    Returns:\n   277\t        Reward score (1.0 for correct, -1.0 for incorrect)\n   278\t    \"\"\"\n   279\t    # Limit solution length for efficiency\n   280\t    solution_str = solution_str[-300:]  # The longest answer in MATH-500 has 159 characters\n   281\t\n   282\t    # Verify the solution\n   283\t    correct, pred = verify(solution_str, ground_truth, strict_box_verify, pause_tokens_index)\n   284\t\n   285\t    reward = 1.0 if correct else -1.0\n   286\t    acc = correct\n   287\t\n   288\t    return {\n   289\t        \"score\": reward,\n   290\t        \"acc\": acc,\n   291\t        \"pred\": pred,\n   292\t    }\n"}}
